const API_TOKEN = '1985d3b7ffcc266add8f005be68caf8ff8ec605f';
const BASE = 'https://api.pipedrive.com/v1';
const DB = 'https://n8n.rnd.webpromo.tools/webhook/pipedrive-db';
const body = $input.first().json.body || $input.first().json;
const entity = body.entity || 'deals';
const dateFrom = body.dateFrom;
const dateTo = body.dateTo;
const BATCH_SQL_SIZE = 100; // rows per single INSERT

async function api(method, path, payload) {
  const opts = {method, url: BASE + path + (path.includes('?') ? '&' : '?') + 'api_token=' + API_TOKEN, timeout: 60000};
  if (payload) {opts.body = payload; opts.headers = {'Content-Type':'application/json'};}
  return await this.helpers.httpRequest(opts);
}

async function db(sql) {
  const r = await this.helpers.httpRequest({method:'POST', url:DB, body:{query:sql}, headers:{'Content-Type':'application/json'}, timeout: 120000});
  if (!r || r === '' || (typeof r === 'string' && r.trim() === '')) {
    throw new Error('DB empty response - SQL failed. SQL head: ' + sql.slice(0,200));
  }
  if (r && r.error) throw new Error('DB error: ' + JSON.stringify(r).slice(0,300));
  if (r && r.success === false) throw new Error('DB failed: ' + JSON.stringify(r).slice(0,300));
  return r;
}

function esc(s) { if(s===null||s===undefined) return ''; return String(s).replace(/\\/g,'\\\\').replace(/'/g,"''").replace(/\x00/g,'').replace(/\n/g,' ').replace(/\r/g,''); }
function sq(s) { return "'" + esc(s) + "'"; }
function sqn(s) { if(s===null||s===undefined||s==='') return 'NULL'; return sq(s); }
function num(n) { if(n===null||n===undefined||n==='') return 'NULL'; return Number(n); }
function b(v) { return v?'true':'false'; }

async function fetchAllPages(path, filterId) {
  const all = [];
  let start=0, hasMore=true, pages=0;
  while(hasMore && pages<100){
    let url = path + (path.includes('?')?'&':'?') + 'limit=500&start='+start;
    if(filterId) url += '&filter_id='+filterId;
    const r = await api.call(this, 'GET', url);
    if(r.data) all.push(...r.data);
    const p = r.additional_data && r.additional_data.pagination;
    hasMore = p && p.more_items_in_collection;
    if(hasMore) start = p.next_start;
    pages++;
  }
  return all;
}

async function batchUpsert(table, rows, buildValues, conflictSet) {
  let inserted = 0, errors = 0, errorSamples = [];
  for(let i=0; i<rows.length; i+=BATCH_SQL_SIZE) {
    const chunk = rows.slice(i, i+BATCH_SQL_SIZE);
    const values = chunk.map(buildValues).filter(v=>v).join(',');
    if(!values) continue;
    const sql = `INSERT INTO pipedrive.${table} VALUES ${values} ON CONFLICT(id) DO UPDATE SET ${conflictSet}`;
    try {
      await db.call(fetchAllPages_ctx, sql);
      inserted += chunk.length;
    } catch(e) {
      errors += chunk.length;
      errorSamples.push({batch:i, error:(e.message||String(e)).slice(0,200)});
    }
  }
  return {inserted, errors, errorSamples};
}

