async function syncEntityInline(endpoint, table, cols, conflict, buildValues) {
  const all = await fetchAllPages.call(fetchAllPages_ctx, endpoint);
  let inserted=0, errors=0, errorSamples=[];
  for(let i=0; i<all.length; i+=BATCH_SQL_SIZE){
    const chunk = all.slice(i, i+BATCH_SQL_SIZE);
    const values = chunk.map(buildValues).join(',');
    const sql = `INSERT INTO pipedrive.${table} ${cols} VALUES ${values} ON CONFLICT(id) DO UPDATE SET ${conflict}`;
    try { await db.call(fetchAllPages_ctx, sql); inserted += chunk.length; }
    catch(e) {
      const parts = values.split('),(');
      for(let j=0; j<parts.length; j++){
        let v = parts[j]; if(j!==0) v='('+v; if(j!==parts.length-1) v=v+')';
        const rowSQL = `INSERT INTO pipedrive.${table} ${cols} VALUES ${v} ON CONFLICT(id) DO UPDATE SET ${conflict}`;
        try { await db.call(fetchAllPages_ctx, rowSQL); inserted++; }
        catch(e2) { errors++; if(errorSamples.length<5) errorSamples.push({id:chunk[j]?.id, error:(e2.message||'').slice(0,150)}); }
