  msg += `\n⏱ Час: *${Math.floor(elapsedAll/60)}хв ${elapsedAll%60}с*`;
  if (errorsAll > 0) msg += `\n❌ Помилок: *${errorsAll}*`;
  msg += `\n🕐 ${new Date().toLocaleString('uk-UA', {timeZone: 'Europe/Kyiv'})}`;

  return [{json: {...r, tg_message: msg, _reportAll:true}}];
}

// Single entity report
const emoji = r.errors > 0 ? '⚠️' : '✅';
const entity = r.entity || 'unknown';
const total = r.total || 0;
const inserted = r.inserted || 0;
const errors = r.errors || 0;
const percent = total > 0 ? Math.round(inserted / total * 10000) / 100 : 0;

let msg = `${emoji} *Pipedrive Sync: ${entity}*\n\n`;
msg += `📊 Всього: *${total}*\n`;
msg += `✅ Збережено: *${inserted}* (${percent}%)\n`;
if (errors > 0) {
  msg += `❌ Помилок: *${errors}*\n\n`;
  if (r.errorSamples && r.errorSamples.length) {
    msg += `_Приклади помилок:_\n`;
    for (const e of r.errorSamples.slice(0, 3)) {
      msg += `• id=${e.id || e.row || '?'}: ${(e.name || e.error || '').toString().slice(0, 80)}\n`;
    }
  }
}
msg += `\n🕐 ${new Date().toLocaleString('uk-UA', {timeZone: 'Europe/Kyiv'})}`;

return [{json: {...r, tg_message: msg}}];
